// Pixel shader for GLSL TOP — no input, procedural output.
// TD auto-injects #version and common uniforms; do NOT add #version yourself.

out vec4 fragColor;

void main() {
    vec2 uv = vUV.st;
    vec3 col = 0.5 + 0.5 * cos(uTime + uv.xyx + vec3(0.0, 2.0, 4.0));
    fragColor = TDOutputSwizzle(vec4(col, 1.0));
}

// Pixel shader for GLSL TOP — 1 input TOP wired into input 0.

out vec4 fragColor;

void main() {
    vec2 uv = vUV.st;
    vec4 src = texture(sTD2DInputs[0], uv);
    // Example: invert RGB, keep alpha
    vec4 col = vec4(1.0 - src.rgb, src.a);
    fragColor = TDOutputSwizzle(col);
}

// Pixel shader for GLSL TOP — 2 inputs, blended by a custom uniform.
// Add a Vectors parameter to the GLSL TOP with Uniform Name = "mix_amount".

uniform float mix_amount;

out vec4 fragColor;

void main() {
    vec2 uv = vUV.st;
    vec4 a = texture(sTD2DInputs[0], uv);
    vec4 b = texture(sTD2DInputs[1], uv);
    fragColor = TDOutputSwizzle(mix(a, b, mix_amount));
}

// Compute shader for GLSL TOP. Set the op's Shader Type to Compute Shader.
// Output goes into mTDComputeOutputs[0]; reading inputs uses sTD2DInputs[N] same as pixel.

layout(local_size_x = 8, local_size_y = 8) in;

void main() {
    ivec2 coord = ivec2(gl_GlobalInvocationID.xy);
    vec2 res = vec2(uTDOutputInfo.res.zw);
    if (coord.x >= int(res.x) || coord.y >= int(res.y)) return;

    vec2 uv = vec2(coord) / res;
    vec3 col = vec3(uv, 0.5 + 0.5 * sin(uTime));
    imageStore(mTDComputeOutputs[0], coord, TDOutputSwizzle(vec4(col, 1.0)));
}
